def compute(vars):
    lease_obligations_2007 = vars["v1"]
    total_commitments_2007 = vars["v2"]

    if total_commitments_2007 == 0:
        return None

    percentage = (lease_obligations_2007 / total_commitments_2007) * 100

    return {
        "value": percentage,
        "trace": {
            "lease_obligations_2007": lease_obligations_2007,
            "total_commitments_2007": total_commitments_2007,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
